/* RevisionCore studio: original lessons, exam practice and account-owned planning. */
const Studio = (() => {
  const $ = s => document.querySelector(s);
  const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const uid = () => crypto.randomUUID();
  const dateISO = (d=new Date()) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  let topics=[], courseTopics=[], practiceTopics=[], libraryIds=new Set(), referenceMode=false, allTopics=[], courses=[], diagrams={}, aiEnabled=false, workspace={}, loaded=false, subject='All subjects', search='', selected=null, exam=null, timer=null, loadGeneration=0;
  const defaults=()=>({notes:[],sessions:[],exams:[],attempts:[],bookmarks:[],completed:[],selected_courses:[],courses_configured:false,folders:[],set_folders:[]});
  let saving=Promise.resolve();
  function icon(name){const paths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',timetable:'<rect x="4" y="5" width="16" height="16" rx="3"/><path d="M8 3v4m8-4v4M4 11h16m-12 4h1m3 0h1m3 0h1m-9 3h1m3 0h1"/>',tasks:'<rect x="5" y="3" width="14" height="18" rx="3"/><path d="m8 10 2 2 5-5M8 16h8"/>',revision:'<path d="m12 3 8 5-8 5-8-5Z"/><path d="m4 12 8 5 8-5m-16 5 8 5 8-5"/>',flashcards:'<rect x="7" y="7" width="14" height="14" rx="3"/><path d="M17 7V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v10a2 2 0 0 0 2 2h2m4-5h6m-6 4h4"/>',notes:'<path d="M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1Zm0 0v15"/>',exam:'<path d="M13 4H5a2 2 0 0 0-2 2v13a2 2 0 0 0 2 2h13a2 2 0 0 0 2-2v-8M16 3l5 5m-11 7 1-5 8-8 5 5-8 8Z"/>',planner:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',insights:'<path d="M4 3v17h17M7 14l4-5 4 3 5-7m-5 0h5v5"/>',assistant:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5ZM20 2v4m-2-2h4"/>',settings:'<path d="m9 3 1 3h4l1-3 3 2-1 3 2 3 3 1-1 4h-3l-2 3v3h-5l-1-3-3-1-3 1-2-4 2-2V9L2 7l3-3 3 1Z"/><circle cx="12" cy="12" r="3"/>',science:'<path d="M9 3h6m-5 0v7L4 20a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1l-6-10V3M7 16h10m-8-3h1m3 5h1"/>',math:'<rect x="4" y="3" width="16" height="18" rx="3"/><path d="M7 7h10m-9 5h1m6 0h1m-8 4h1m6 0h1"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.notes}</svg>`;}
  function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(window._toast);window._toast=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
  async function api(url, options={}) {
    const response=await fetch(url,{credentials:'same-origin',headers:{'Content-Type':'application/json'},...options});
    const result=await response.json();
    if(!response.ok)throw new Error(result.error||'Could not complete this action.');
    return result;
  }
  async function persist(){
    const snapshot=JSON.stringify(workspace);
    const owner=Hub.getData().profile?.username;
    const action=saving.then(()=>{if(Hub.getData().profile?.username!==owner||document.body.classList.contains('logged-out'))throw new Error('Sign in again before saving.');return api('/api/study/workspace',{method:'PUT',body:snapshot});});
    saving=action.catch(()=>{});
    try{await action;$('#studioSaveError')?.remove();return true;}catch(error){toast(error.message);showSaveRetry();return false;}
  }
  function showSaveRetry(){let banner=$('#studioSaveError');if(!banner){banner=document.createElement('div');banner.id='studioSaveError';banner.className='save-error';$('.hub-main').prepend(banner);}banner.innerHTML='<span>Changes have not been saved to your account.</span><button class="small-button">Retry save</button>';banner.querySelector('button').onclick=async()=>{if(await persist()){banner.remove();toast('Changes saved.');}};}
  async function load(){
    const generation=++loadGeneration;
    try{
      const [catalog,result,artwork]=await Promise.all([fetch('/static/curriculum.json').then(r=>{if(!r.ok)throw new Error('Lesson library unavailable.');return r.json();}),api('/api/study/workspace'),fetch('/static/diagrams.json').then(r=>{if(!r.ok)throw new Error('Teaching diagrams unavailable.');return r.json();})]);
      if(generation!==loadGeneration)return;
      allTopics=catalog.topics;libraryIds=new Set(catalog.note_library_ids||catalog.topics.map(t=>t.id));courses=catalog.courses;diagrams=artwork;workspace={...defaults(),...result.workspace};applyCourses();loaded=true;renderAll();api('/api/study/config').then(c=>{aiEnabled=c.ai_marking;}).catch(()=>{});if(!workspace.courses_configured)coursePicker();
    }catch(error){loaded=false;for(const id of ['notes','exam','planner','insights'])$(`#view-${id}`).innerHTML=`<div class="panel"><h2>Your study workspace could not load</h2><p>${esc(error.message)}</p><button class="primary-button" data-reload>Try again</button></div>`;document.querySelectorAll('[data-reload]').forEach(b=>b.onclick=load);}
  }
  function heading(kicker,title,description,actions=''){return `<div class="section-title"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${description}</p></div><div class="section-actions">${actions}</div></div>`;}
  const subjects=()=>[...new Set(topics.map(t=>t.subject))];
  function options(all=true){return (all?['All subjects']:[]).concat(subjects()).map(s=>`<option ${s===subject?'selected':''}>${esc(s)}</option>`).join('');}
  function matching(pool=topics){return pool.filter(t=>(subject==='All subjects'||t.subject===subject)&&`${t.title} ${t.subject} ${t.chapter} ${t.sections.map(s=>s.heading).join(' ')} ${(t.key_terms||[]).map(k=>k.term).join(' ')} ${t.practical?'practical':''}`.toLowerCase().includes(search.toLowerCase()));}

  function applyCourses(){
    const picks=new Map((workspace.selected_courses||[]).map(c=>[c.id,c]));
    courseTopics=allTopics.filter(t=>{const pick=picks.get(t.course_id);return pick&&(t.course_id!=='0445'||t.track==='Common'||t.track===pick.option)&&(pick.tier!=='Foundation'||t.tier!=='Higher');});
    practiceTopics=courseTopics.filter(t=>t.questions.length);topics=referenceMode?courseTopics.filter(t=>!libraryIds.has(t.id)):[...libraryIds].map(id=>courseTopics.find(t=>t.id===id)).filter(Boolean);
    if(!subjects().includes(subject))subject='All subjects';
    if(!topics.some(t=>t.id===selected))selected=null;
  }
  function coursePicker(){
    modal(`<span class="eyebrow">Built around your exams</span><h2>Your courses. Your path.</h2><p class="modal-subtitle">Choose your subjects and qualification details. Notes, questions and targeted practice will follow these choices.</p><form id="coursePicker"><div class="course-choices">${courses.map(c=>{const picked=workspace.selected_courses.find(p=>p.id===c.id);return `<div class="course-choice"><label class="course-check"><input type="checkbox" name="course" value="${c.id}" ${picked?'checked':''}><span><strong>${esc(c.subject)}</strong><small>${esc(c.board)} · ${esc(c.qualification)} · ${c.id}</small></span></label><div class="course-choice-options"><label>Exam year<select data-year="${c.id}">${c.years.map(y=>`<option ${y===(picked?.year||2027)?'selected':''}>${y}</option>`).join('')}</select></label>${c.tiers.length?`<label>Tier<select data-tier="${c.id}">${c.tiers.map(t=>`<option ${t===(picked?.tier||'Higher')?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`:''}${c.options.length?`<label>Specialist option<select data-option="${c.id}">${c.options.map(o=>`<option ${o===(picked?.option||'Resistant Materials')?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`:''}</div></div>`;}).join('')}</div><p class="muted">The 0445 edition here is for 2027. The Cambridge course changes from 2028, so that edition needs its own reviewed content.</p><p id="courseError" role="alert"></p><div class="reader-actions"><button type="button" class="small-button" id="chooseAllCourses">Select my six subjects</button><button class="primary-button" id="saveCourses">Save my courses</button></div></form>`);
    $('#chooseAllCourses').onclick=()=>document.querySelectorAll('#coursePicker input[type=checkbox]').forEach(c=>c.checked=true);
    $('#coursePicker').onsubmit=async e=>{e.preventDefault();if($('#studioSaveError')){$('#courseError').textContent='Retry saving your unsaved workspace before changing courses.';return;}const selectedCourses=[...e.target.querySelectorAll('input:checked')].map(c=>({id:c.value,year:Number($(`[data-year="${c.value}"]`).value),tier:$(`[data-tier="${c.value}"]`)?.value||'',option:$(`[data-option="${c.value}"]`)?.value||''}));if(!selectedCourses.length){$('#courseError').textContent='Choose at least one course to build your library.';return;}$('#saveCourses').disabled=true;try{await saving;const result=await api('/api/study/courses',{method:'PUT',body:JSON.stringify({courses:selectedCourses})});workspace={...defaults(),...result.workspace};applyCourses();close();await Hub.load();renderAll();toast('Your course library is ready.');}catch(error){$('#courseError').textContent=error.message;$('#saveCourses').disabled=false;}};
  }
  function teachingFigure(kind){
    const illustrations={cell:'<rect x="30" y="20" width="190" height="110" rx="35"/><ellipse cx="120" cy="75" rx="27" ry="20"/><path d="M147 75h83m-190 35h190"/><text x="240" y="79">Nucleus: genetic information</text><text x="240" y="114">Membrane: selective boundary</text>',wave:'<path d="M20 80Q65 10 110 80T200 80T290 80T380 80"/><path d="M65 25h180"/><text x="85" y="18">One wavelength</text><text x="300" y="137">Energy transfer →</text>',motion:'<path d="M50 20v110h410M50 110 360 40"/><text x="160" y="43">Gradient = acceleration</text><text x="110" y="148">Area = displacement</text>',cpu:'<rect x="20" y="50" width="120" height="60" rx="10"/><rect x="200" y="50" width="120" height="60" rx="10"/><rect x="380" y="50" width="105" height="60" rx="10"/><path d="M140 80h60m120 0h60"/><text x="43" y="84">Memory</text><text x="217" y="84">Control unit</text><text x="417" y="84">ALU</text>',inheritance:'<path d="M60 25h160v100H60Zm80 0v100M60 75h160"/><text x="83" y="56">TT</text><text x="163" y="56">Tt</text><text x="83" y="107">Tt</text><text x="163" y="107">tt</text><text x="270" y="68">Tt × Tt</text><text x="270" y="100">¼ recessive phenotype</text>',circuit:'<path d="M60 80V30h120m80 0h170v95H60V94"/><rect x="180" y="18" width="80" height="24"/><path d="M50 80h20m-16 14h12"/><text x="211" y="35">R</text><text x="160" y="151">A complete conducting loop</text>'};
    return illustrations[kind]?`<figure class="teaching-figure"><svg viewBox="0 0 520 165" role="img" aria-label="${esc(kind)} teaching diagram">${illustrations[kind]}</svg></figure>`:'';
  }


  function sceneSVG(key){
    const d=diagrams[key];if(!d)return '';const a=(name,value)=>` ${name}="${esc(value)}"`;
    const common=e=>a('stroke',e.color||'#172a3e')+a('stroke-width',e.width||2)+a('fill',e.fill||'none')+(e.dash?' stroke-dasharray="5 5"':'');
    const elements=d.elements.map(e=>{
      if(e.kind==='text')return `<text${a('x',e.x)+a('y',e.y)+a('font-size',e.size||18)+a('fill',e.color||'#172a3e')+a('text-anchor',e.anchor||'start')} stroke="none">${esc(e.text)}</text>`;
      if(e.kind==='line'||e.kind==='arrow'){
        let out=`<line${a('x1',e.x1)+a('y1',e.y1)+a('x2',e.x2)+a('y2',e.y2)+common(e)}/>`;
        if(e.kind==='arrow'){const angle=Math.atan2(e.y2-e.y1,e.x2-e.x1);out+=`<polyline${a('points',[-.45,0,.45].map((off,i)=>i===1?`${e.x2},${e.y2}`:`${e.x2-10*Math.cos(angle+off)},${e.y2-10*Math.sin(angle+off)}`).join(' '))+common(e)}/>`;}return out;
      }
      if(e.kind==='path'){const valid=e.commands.every(c=>['M','L','C','Q','Z'].includes(c[0])&&c.slice(1).every(Number.isFinite));return valid?`<path${a('d',e.commands.map(c=>c[0]+' '+c.slice(1).join(' ')).join(' '))+common(e)}/>`:'';}
      if(e.kind==='rect')return `<rect${a('x',e.x)+a('y',e.y)+a('width',e.w)+a('height',e.h)+a('rx',e.r||0)+common(e)}/>`;
      if(e.kind==='ellipse')return `<ellipse${a('cx',e.cx)+a('cy',e.cy)+a('rx',e.rx)+a('ry',e.ry)+common(e)}/>`;
      if(['polygon','polyline'].includes(e.kind))return `<${e.kind}${a('points',e.points.map(v=>v.join(',')).join(' '))+common(e)}/>`;
      return '';
    }).join('');
    return `<svg viewBox="0 0 ${d.width} ${d.height}" role="img" aria-label="${esc(d.title+'. '+d.alt)}" xmlns="http://www.w3.org/2000/svg"><title>${esc(d.title)}</title><desc>${esc(d.alt)}</desc>${elements}</svg>`;
  }
  function sceneFigure(key){const d=diagrams[key];return d?`<figure class="lesson-diagram"><div class="diagram-canvas">${sceneSVG(key)}</div><figcaption><strong>${esc(d.title)}</strong><span>${esc(d.caption)}</span></figcaption><button class="text-button diagram-expand" data-expand-diagram="${esc(key)}" aria-label="Enlarge ${esc(d.title)}">Enlarge diagram ↗</button></figure>`:'';}

  function prose(body){return String(body||'').split(/\n\s*\n/).filter(Boolean).map(part=>`<p>${esc(part)}</p>`).join('');}
  function comparisonTable(table){return table?`<div class="comparison-scroll"><table class="revision-comparison"><thead><tr>${table.headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${table.rows.map(row=>`<tr>${row.map(cell=>`<td>${esc(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'';}
  function renderNotes(){
    const el=$('#view-notes');
    el.innerHTML=heading('RevisionCore / Your course library','Revision notes','Learn the ideas, follow the reasoning, then test your recall.','<button class="small-button" id="courseOverview">Course overview</button><button class="small-button" id="chooseCourses">My courses</button><button class="small-button" id="importNote">Import notes</button><button class="primary-button" id="newNote">＋ Personal note</button>')+`<div id="courseMap" class="course-map panel" hidden></div><div class="library-toolbar"><label class="search-field"><span>⌕</span><input id="noteSearch" type="search" placeholder="Search topics, key terms or practicals" value="${esc(search)}"></label><select id="noteSubject" aria-label="Filter notes by subject">${options()}</select><button class="small-button" id="referenceLessons">${referenceMode?"Topic guides":"More detailed lessons"}</button><button class="small-button" id="bookmarkedOnly">☆ Saved topics</button></div><div class="library-caption">${topics.length} ${referenceMode?"additional lessons":"topic guides"} · ${referenceMode?"Extra explanation and existing practice":"Organised for your exam board"}</div><div class="note-layout"><nav id="topicList" class="topic-list" aria-label="Course topics"></nav><article id="noteReader" class="note-reader panel"></article></div><div class="panel own-notes"><div class="panel-head"><div><span class="eyebrow">Your understanding, in your words</span><h3>Personal notebook</h3></div><span>${workspace.notes.length} notes</span></div><div id="ownNotes" class="note-grid"></div></div>`;
    let onlySaved=false,readingTab='learn';
    const filtered=()=>matching(onlySaved?courseTopics:topics).filter(t=>!onlySaved||workspace.bookmarks.includes(t.id));
    function list(){const caption=$('.library-caption');if(caption)caption.textContent=`${filtered().length} ${onlySaved?'saved topics':referenceMode?'additional lessons':'topic guides'}${subject==='All subjects'?'':' · '+subject} · Organised for your exam board`;const groups=new Map();for(const t of filtered()){const key=t.subject+' / '+t.chapter;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(t);}$('#topicList').innerHTML=[...groups].map(([name,items])=>`<details class="topic-group" open><summary>${esc(name)} <b>${items.filter(t=>workspace.completed.includes(t.id)).length}/${items.length}</b></summary>${items.map(t=>`<button class="topic-button ${selected===t.id?'selected':''}" data-topic="${t.id}" ${selected===t.id?'aria-current="page"':''}><strong>${esc(t.title)}</strong><small>${t.code} · ${t.sections.length} sections · ${t.minutes} min ${workspace.completed.includes(t.id)?'· ✓ Read':''} ${workspace.bookmarks.includes(t.id)?'· ★':''}</small></button><details class="topic-section-list"><summary>In this topic</summary>${t.sections.map((part,i)=>`<button data-open-section="${t.id}" data-part="${i}">${esc(part.heading)}</button>`).join('')}</details>`).join('')}</details>`).join('')||'<div class="empty">No matching lessons. Change the search or choose your courses.</div>';$('#topicList').querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>{selected=b.dataset.topic;readingTab='learn';list();reader();});$('#topicList').querySelectorAll('[data-open-section]').forEach(b=>b.onclick=()=>{selected=b.dataset.openSection;readingTab='learn';const part=b.dataset.part;reader();list();$('#readerPart'+part)?.scrollIntoView({behavior:'smooth',block:'start'});});}
    function reader(){
      const t=courseTopics.find(t=>t.id===selected)||filtered()[0];
      if(!t){$('#noteReader').innerHTML='<div class="library-empty"><span>▧</span><h2>A library that fits your exams.</h2><p>Choose your subjects and exam details to see the right lessons.</p><button class="primary-button" id="emptyChooseCourses">Choose my courses</button></div>';$('#emptyChooseCourses').onclick=coursePicker;return;}
      selected=t.id;const practiceSource=t.questions.length?t:(courseTopics.find(x=>x.id===t.parent_topic)||t);const pick=workspace.selected_courses.find(c=>c.id===t.course_id),examples=t.worked_examples||[t.worked],terms=t.key_terms||[];
      const pool=(topics.some(x=>x.id===t.id)?topics:courseTopics).filter(x=>x.course_id===t.course_id),index=pool.findIndex(x=>x.id===t.id),related=(t.related_topics||[]).map(id=>courseTopics.find(x=>x.id===id)).filter(Boolean),independent=t.questions.filter(q=>q.purpose==='Independent practice'),further=(t.source_topics||[]).map(id=>courseTopics.find(x=>x.id===id)).filter(Boolean);
      $('#noteReader').innerHTML=`<div class="reader-top"><span class="badge">${esc(t.board)} · ${t.code} · ${pick?.year||2027}</span><button class="icon-button" id="bookmarkTopic" aria-label="${workspace.bookmarks.includes(t.id)?'Unsave':'Save'} topic">${workspace.bookmarks.includes(t.id)?'★':'☆'}</button></div><div class="reader-chapter">${esc(t.chapter)}</div><h2>${esc(t.title)}</h2><p class="reader-deck">${esc(t.qualification)} · ${t.minutes} min reading · ${t.sections.length} explanations</p><div class="reader-tabs" role="tablist" aria-label="Revision lesson sections"><button role="tab" id="tabLearn" data-reader-tab="learn" aria-controls="panelLearn" aria-selected="${readingTab==='learn'}">Learn</button><button role="tab" id="tabWorked" data-reader-tab="worked" aria-controls="panelWorked" aria-selected="${readingTab==='worked'}">Worked examples ${examples.length?`<span>${examples.length}</span>`:''}</button><button role="tab" id="tabRecall" data-reader-tab="recall" aria-controls="panelRecall" aria-selected="${readingTab==='recall'}">${t.questions.length?`Quick check <span>${t.questions.length}</span>`:'Recall practice'}</button></div>
      <div id="panelLearn" role="tabpanel" aria-labelledby="tabLearn" ${readingTab!=='learn'?'hidden':''}>
        ${t.plain_intro?`<aside class="plain-intro"><span class="eyebrow">Start here</span>${prose(t.plain_intro)}</aside>`:''}
        ${t.scope_note?`<p class="lesson-scope">${esc(t.scope_note)}</p>`:''}${t.prerequisite?`<p class="lesson-prerequisite"><strong>Before you begin</strong> ${esc(t.prerequisite)}</p>`:''}<aside class="learning-objectives"><span class="eyebrow">In this lesson</span><ul>${(t.objectives||t.sections.slice(0,3).map(s=>s.heading)).map(o=>`<li>${esc(o)}</li>`).join('')}</ul></aside>
        ${t.concept_flow?`<ol class="concept-flow" aria-label="Key idea sequence">${t.concept_flow.map((step,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><strong>${esc(step)}</strong></li>`).join('')}</ol>`:''}<div class="reader-contents">${t.sections.map((s,i)=>`<a href="#readerPart${i}">${String(i+1).padStart(2,'0')} ${esc(s.heading)}</a>`).join('')}</div>
        ${t.child_topics?.length?`<section class="focused-lessons"><span class="eyebrow">Go deeper</span><h3>Focused lessons in this chapter</h3><div>${t.child_topics.map(id=>courseTopics.find(x=>x.id===id)).filter(Boolean).map(x=>`<button class="focused-lesson" data-related-topic="${esc(x.id)}"><strong>${esc(x.title)}</strong><small>${x.minutes} min · Illustrated notes →</small></button>`).join('')}</div></section>`:''}${t.sections.map((s,i)=>`<section id="readerPart${i}" class="reading-section"><span class="section-number">${String(i+1).padStart(2,'0')}</span><h3>${esc(s.heading)}</h3>${prose(s.body)}${(s.figures||[]).map(sceneFigure).join('')}</section>`).join('')}
        ${t.formula?`<div class="formula-card"><span>THE RELATIONSHIP</span><strong>${esc(t.formula)}</strong></div>`:''}${teachingFigure(t.diagram)}${comparisonTable(t.comparison_table)}
        ${t.code_example?`<section class="code-block"><h3>${t.code_example.trim().startsWith('SELECT')?'Read the query':'Follow the algorithm'}</h3><pre><code>${esc(t.code_example)}</code></pre><p class="muted">${t.code_example.trim().startsWith('SELECT')?'SQL query example. Identify the selected fields, condition and output order.':'Language-neutral pseudocode. Helper names describe their intended operation; trace the values before reading the worked examples.'}</p></section>`:''}
        ${t.practical?`<section class="practical-card"><span class="eyebrow">Practical understanding</span><h3>${esc(t.practical.aim)}</h3><p><strong>Measure:</strong> ${esc(t.practical.measure)}</p><h4>Keep the comparison fair</h4><ul>${t.practical.controls.map(c=>`<li>${esc(c)}</li>`).join('')}</ul><p>${esc(t.practical.evaluation)}</p></section>`:''}
        ${terms.length?`<section class="key-terms"><h3>Know the language</h3><dl>${terms.map(term=>`<div><dt>${esc(term.term)}</dt><dd>${esc(term.definition)}</dd></div>`).join('')}</dl></section>`:''}
        <aside class="exam-tip"><strong>Exam technique</strong><p>${esc(t.tip)}</p></aside>${t.misconception&&t.misconception!==t.tip?`<aside class="misconception-card"><strong>Avoid this mistake</strong><p>${esc(t.misconception)}</p></aside>`:''}
      </div>
      <div id="panelWorked" role="tabpanel" aria-labelledby="tabWorked" ${readingTab!=='worked'?'hidden':''}>${!examples.length?'<p class="recall-intro">Open a linked detailed lesson below for worked reasoning and examples.</p>':''}${examples.map((ex,i)=>`<section class="worked-example"><span class="eyebrow">Worked example ${i+1}</span><h3>${esc(ex.question)}</h3><details class="worked-solution"><summary>Show the reasoning</summary><ol>${ex.steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol></details>${t.questions[i]?`<button class="text-button" data-example-practice="${i}">Try this in practice mode →</button>`:''}</section>`).join('')}</div>
      <div id="panelRecall" role="tabpanel" aria-labelledby="tabRecall" ${readingTab!=='recall'?'hidden':''}>${!t.questions.length?'<p class="recall-intro">Use the linked chapter practice for existing questions, or ask Rian to check your understanding of these notes.</p>':'<p class="recall-intro">Close the explanation. Answer from memory, then compare your reasoning. Practice mode saves your results and offers Rian AI marking.</p>'}${t.questions.map((q,i)=>`<section class="recall-question"><div><span class="question-number">${String(i+1).padStart(2,'0')}</span><span class="badge">${q.marks} ${q.marks===1?'mark':'marks'} · ${esc(q.difficulty)}</span></div>${q.purpose?`<span class="question-purpose">${esc(q.purpose)}</span>`:''}<h3>${esc(q.prompt)}</h3><details><summary>Reveal answer and marking points</summary><ol>${q.mark_scheme.map(p=>`<li>${esc(p.text)} <span>${p.marks} mark</span></li>`).join('')}</ol></details><button class="text-button" data-single-practice="${i}">Answer in practice mode →</button></section>`).join('')}</div>
      <div class="reader-actions"><button class="primary-button" id="markRead">${workspace.completed.includes(t.id)?'✓ Read':'Mark as read'}</button><button class="small-button" id="practiceTopic" ${practiceSource.questions.length?'':'disabled'}>${t.questions.length?'Practise this topic':'Practise linked chapter'}</button>${independent.length?'<button class="small-button" id="independentTopic">Independent practice</button>':''}<button class="small-button" id="topicCards" ${practiceSource.cards.length?'':'disabled'}>${t.cards.length?'Study flashcards':'Chapter flashcards'}</button></div><div class="note-download-row"><a class="small-button" href="/api/study/notes/${t.id}.pdf">↓ Notes PDF</a><a class="text-button" href="/api/study/courses/${t.course_id}.pdf?option=${encodeURIComponent(pick?.option||'')}">Subject PDF</a><button class="text-button" id="explainTopic">✦ Explain with Rian</button></div>${further.length?`<section class="related-lessons further-reading"><span class="eyebrow">More explanation</span><h3>Detailed lessons & worked reasoning</h3><div>${further.map(x=>`<button data-related-topic="${esc(x.id)}"><strong>${esc(x.title)}</strong><small>${x.sections.length} explanations · ${x.worked_examples.length} worked examples →</small></button>`).join('')}</div></section>`:''}${related.length?`<section class="related-lessons"><span class="eyebrow">Build on this</span><h3>Connected lessons</h3><div>${related.map(x=>`<button data-related-topic="${esc(x.id)}"><span>${esc(x.chapter)}</span><strong>${esc(x.title)}</strong><small>${x.minutes} min${x.worked_examples?.length?' · '+x.worked_examples.length+' worked examples':''} →</small></button>`).join('')}</div></section>`:''}<div class="topic-pagination"><button class="text-button" id="previousTopic" ${index<=0?'disabled':''}>← Previous lesson</button><span>${index+1} / ${pool.length}</span><button class="text-button" id="nextTopic" ${index>=pool.length-1?'disabled':''}>Next lesson →</button></div><p class="reader-reference"><a href="${esc(t.source)}" target="_blank" rel="noopener">Official ${t.code} specification ↗</a> · Original RevisionCore edition. Independent subject-teacher review and a full statement-by-statement coverage audit remain pending.</p>`;
      document.querySelectorAll('[data-reader-tab]').forEach(b=>{b.tabIndex=b.dataset.readerTab===readingTab?0:-1;b.onclick=()=>{readingTab=b.dataset.readerTab;reader();$(`[data-reader-tab="${readingTab}"]`).focus();};b.onkeydown=e=>{const tabs=['learn','worked','recall'],i=tabs.indexOf(readingTab);let next;if(e.key==='ArrowRight')next=(i+1)%3;if(e.key==='ArrowLeft')next=(i+2)%3;if(e.key==='Home')next=0;if(e.key==='End')next=2;if(next===undefined)return;e.preventDefault();readingTab=tabs[next];reader();$(`[data-reader-tab="${readingTab}"]`).focus();};});
      document.querySelectorAll('[data-expand-diagram]').forEach(b=>b.onclick=()=>{const key=b.dataset.expandDiagram;modal(`<div class="diagram-modal"><span class="eyebrow">Teaching diagram</span><h2>${esc(diagrams[key].title)}</h2><div class="diagram-pan">${sceneSVG(key)}</div><p>${esc(diagrams[key].caption)}</p><small>On a narrow screen, scroll within the diagram to read the labels at full size.</small></div>`);});
      $('#bookmarkTopic').onclick=async()=>{const i=workspace.bookmarks.indexOf(t.id);i<0?workspace.bookmarks.push(t.id):workspace.bookmarks.splice(i,1);await persist();reader();list();};
      $('#markRead').onclick=async()=>{const i=workspace.completed.indexOf(t.id);i<0?workspace.completed.push(t.id):workspace.completed.splice(i,1);await persist();reader();list();renderInsights();};
      const practice=questions=>{Hub.go('exam');startExam(questions,0);};$('#practiceTopic').onclick=()=>practice(practiceSource.questions);if($('#independentTopic'))$('#independentTopic').onclick=()=>practice(independent);document.querySelectorAll('[data-related-topic]').forEach(b=>b.onclick=()=>{selected=b.dataset.relatedTopic;readingTab='learn';reader();list();$('#noteReader').scrollIntoView({behavior:'smooth',block:'start'});});document.querySelectorAll('[data-single-practice]').forEach(b=>b.onclick=()=>practice([t.questions[Number(b.dataset.singlePractice)]]));document.querySelectorAll('[data-example-practice]').forEach(b=>b.onclick=()=>practice([t.questions[Number(b.dataset.examplePractice)]]));
      $('#topicCards').onclick=()=>cardsFromTopic(practiceSource);$('#explainTopic').onclick=()=>askTutor(`I study ${t.board} ${t.qualification} ${t.code}, exam ${pick?.year||2027}. Help me understand ${t.title}. Use this context: ${t.sections.map(s=>s.body).join(' ').slice(0,5000)}. Explain the reasoning, then ask one retrieval question. Do not fabricate assessed-project evidence.`);
      for(const [id,offset] of [['previousTopic',-1],['nextTopic',1]])$('#'+id).onclick=()=>{const next=pool[index+offset];if(!next)return;selected=next.id;readingTab='learn';reader();list();$('#noteReader').scrollIntoView({behavior:'smooth',block:'start'});};
    }
    $('#noteSearch').oninput=e=>{search=e.target.value;list();};$('#noteSubject').onchange=e=>{subject=e.target.value;selected=null;readingTab='learn';reader();list();};$('#referenceLessons').onclick=()=>{referenceMode=!referenceMode;selected=null;applyCourses();renderNotes();};$('#bookmarkedOnly').onclick=e=>{onlySaved=!onlySaved;e.currentTarget.classList.toggle('active',onlySaved);list();};$('#chooseCourses').onclick=coursePicker;$('#newNote').onclick=()=>editNote();$('#importNote').onclick=importNote;
    $('#courseOverview').onclick=()=>{const map=$('#courseMap');map.hidden=!map.hidden;if(map.hidden)return;map.innerHTML=`<div class="panel-head"><div><span class="eyebrow">Your exam-board routes</span><h3>Course overview</h3></div><span class="muted">Available lessons and reading progress</span></div><div class="course-overview-grid">${workspace.selected_courses.map(pick=>{const c=courses.find(c=>c.id===pick.id),items=topics.filter(t=>t.course_id===pick.id),read=items.filter(t=>workspace.completed.includes(t.id)).length;return `<button data-map-course="${esc(c.subject)}"><span class="badge">${c.id} · ${pick.year}</span><h3>${esc(c.subject)}</h3><p>${esc(c.board)}${pick.option?' · '+esc(pick.option):''}</p><div class="progress-track"><i style="width:${items.length?read/items.length*100:0}%"></i></div><small>${read} of ${items.length} lessons read</small></button>`;}).join('')}</div><p class="muted">This map lists the included material. It is not certification that every specification statement has been covered.</p>`;map.querySelectorAll('[data-map-course]').forEach(b=>b.onclick=()=>{subject=b.dataset.mapCourse;selected=null;renderNotes();});};
    reader();list();renderOwnNotes();
  }
  function renderOwnNotes(){if(!$('#ownNotes'))return;$('#ownNotes').innerHTML=workspace.notes.map(n=>`<button class="personal-note" data-note="${esc(n.id)}"><span class="badge">${esc(n.subject||'Personal')}</span><h3>${esc(n.title)}</h3><p>${esc(n.body.slice(0,110))}…</p></button>`).join('')||'<div class="empty">Your explanations, class notes and exam tips belong here.</div>';$('#ownNotes').querySelectorAll('[data-note]').forEach(b=>b.onclick=()=>editNote(workspace.notes.find(n=>n.id===b.dataset.note)));}
  let previousFocus;
  function modal(content){previousFocus=document.activeElement;$('#modalContent').innerHTML=content;$('#modal').hidden=false;$('#modal').setAttribute('role','dialog');$('#modal').setAttribute('aria-modal','true');$('#modal').setAttribute('aria-label','Study workspace');setTimeout(()=>$('#modalContent input, #modalContent textarea, #modalContent button')?.focus(),0);}
  function close(){ $('#modal').hidden=true;previousFocus?.focus(); }
  function editNote(note={}){const draftId=note.id||uid();modal(`<span class="eyebrow">Your notebook</span><h2>${note.id?'Edit note':'Write a note'}</h2><form id="noteForm" class="modal-form"><label>Title<input name="title" required maxlength="160" value="${esc(note.title)}"></label><div class="form-two"><label>Subject<input name="subject" maxlength="80" value="${esc(note.subject)}" placeholder="e.g. Biology"></label><label>Exam board<input name="board" maxlength="80" value="${esc(note.board)}" placeholder="e.g. AQA"></label></div><label>Your notes<textarea name="body" rows="12" required maxlength="30000" placeholder="Explain the topic in your own words…">${esc(note.body)}</textarea></label><div class="reader-actions"><button class="primary-button">Save note</button><button type="button" class="small-button" id="notePrint">Print / PDF</button>${note.id?'<button type="button" class="text-button danger" id="deleteNote">Delete</button>':''}</div></form>`);$('#noteForm').onsubmit=async e=>{e.preventDefault();const form=new FormData(e.target),item={id:draftId,...Object.fromEntries(form)};const i=workspace.notes.findIndex(n=>n.id===item.id);i<0?workspace.notes.push(item):workspace.notes.splice(i,1,item);if(await persist()){close();renderNotes();toast('Note saved.');}};$('#notePrint').onclick=()=>{const f=new FormData($('#noteForm'));printContent(f.get('title'),`<h1>${esc(f.get('title'))}</h1><div style="white-space:pre-wrap">${esc(f.get('body'))}</div>`);};if(note.id)$('#deleteNote').onclick=async()=>{if(!confirm('Delete this note?'))return;workspace.notes=workspace.notes.filter(n=>n.id!==note.id);if(await persist()){close();renderNotes();}};}
  function importNote(){modal('<h2>Bring your notes</h2><p>Import a text or Markdown file. You can edit it before saving.</p><label class="file-drop">Choose .txt or .md file<input id="noteFile" type="file" accept=".txt,.md,text/plain,text/markdown"></label>');$('#noteFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>120000){toast('Choose a file smaller than 120 KB.');return;}editNote({title:f.name.replace(/\.[^.]+$/,''),body:(await f.text()).slice(0,30000)});};}
  async function cardsFromTopic(t){try{const text=t.cards.map(c=>`${c.question}\t${c.answer}`).join('\n');const result=await api('/api/student/flashcards/import',{method:'POST',body:JSON.stringify({text,deck:t.title,subject:t.subject,format:'txt'})});await Hub.load();Hub.go('flashcards');toast(`${result.added} cards added${result.duplicates?' · existing cards skipped':''}.`);}catch(e){toast(e.message);}}
  function askTutor(prompt){Hub.go('assistant');$('#prompt').value=prompt;$('#prompt').focus();}
  function allQuestions(){return practiceTopics.flatMap(t=>t.questions.map(q=>({...q,topic:t.title,subject:t.subject,topicId:t.id,course_id:t.course_id,board:t.board})));}
  function enrich(q){return allQuestions().find(x=>x.id===q.id)||q;}
  function topicAccuracy(topic){const guide=topics.find(t=>t.title===topic),names=new Set([topic,...(guide?.source_topics||[]).map(id=>allTopics.find(t=>t.id===id)?.title)].filter(Boolean));const attempts=workspace.attempts.filter(a=>names.has(a.topic));const total=attempts.reduce((s,a)=>s+a.total,0);return total?Math.round(attempts.reduce((s,a)=>s+a.marks,0)/total*100):null;}
  function renderExam(){if(exam)return;const el=$('#view-exam');el.innerHTML=heading('Exam ready','Practice with purpose','Build a paper, target your weaker topics, and learn from every answer.')+`<div class="exam-launch-grid"><article class="feature-card blue"><span class="feature-symbol">◎</span><h2>Target test</h2><p>Questions from topics where your recorded scores are lowest. Unseen topics come next.</p><button class="primary-button" id="targetTest">Target my gaps →</button></article><article class="feature-card gold"><span class="feature-symbol">◷</span><h2>Timed mock</h2><p>A focused practice paper from the original question bank. Mark it against model answers.</p><button class="primary-button" id="mockTest">Start 20-minute mock →</button></article></div><article class="panel"><div class="panel-head"><div><span class="eyebrow">Make it yours</span><h3>Test builder</h3></div><span class="badge">${allQuestions().length} original practice questions</span></div><form id="testBuilder" class="builder"><label>Subject<select id="examSubject">${options()}</select></label><label>Topic<select id="examTopic"><option value="all">All topics</option></select></label><label>Difficulty<select id="examDifficulty"><option>All</option><option>Core</option><option>Develop</option><option>Challenge</option></select></label><label>Questions<input id="examCount" type="number" min="1" max="40" value="8"></label><label>Minutes<input id="examMinutes" type="number" min="0" max="180" value="0"></label><button class="primary-button">Build test</button></form><p class="muted">0 minutes = untimed. Original course-specific practice; these are not official past papers.</p></article><article class="panel paper-links"><span class="eyebrow">From the source</span><h3>Official past papers & specifications</h3><p>Use your board’s official resources alongside the original practice bank.</p><div class="reader-actions"><a href="https://www.aqa.org.uk/find-past-papers-and-mark-schemes" target="_blank" rel="noopener">AQA ↗</a><a href="https://qualifications.pearson.com/en/support/support-topics/exams/past-papers.html" target="_blank" rel="noopener">Pearson Edexcel ↗</a><a href="https://www.ocr.org.uk/qualifications/past-paper-finder/" target="_blank" rel="noopener">OCR ↗</a><a href="https://www.bbc.co.uk/bitesize" target="_blank" rel="noopener">Bitesize lessons ↗</a></div></article>`;
    const updateTopics=()=>{const s=$('#examSubject').value;$('#examTopic').innerHTML='<option value="all">All topics</option>'+practiceTopics.filter(t=>s==='All subjects'||t.subject===s).map(t=>`<option value="${t.id}">${esc(t.title)}</option>`).join('');};$('#examSubject').onchange=updateTopics;updateTopics();
    $('#testBuilder').onsubmit=e=>{e.preventDefault();const s=$('#examSubject').value,t=$('#examTopic').value,d=$('#examDifficulty').value;const qs=allQuestions().filter(q=>(s==='All subjects'||q.subject===s)&&(t==='all'||q.topicId===t)&&(d==='All'||q.difficulty===d));if(!qs.length){toast('No questions match those filters.');return;}startExam(shuffle(qs).slice(0,Math.max(1,Number($('#examCount').value))),Number($('#examMinutes').value));};
    $('#targetTest').onclick=()=>{const ranked=practiceTopics.slice().sort((a,b)=>(topicAccuracy(a.title)??50)-(topicAccuracy(b.title)??50));startExam(ranked.slice(0,5).flatMap(t=>t.questions.slice(0,1)),0);};$('#mockTest').onclick=()=>startExam(shuffle(allQuestions()).slice(0,10),20);
  }
  const shuffle=a=>{const result=a.slice();for(let i=result.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[result[i],result[j]]=[result[j],result[i]];}return result;};
  function startExam(questions,minutes){if(!questions.length){toast('Choose your courses before starting practice.');coursePicker();return;}stopTimer();exam={questions:questions.map(enrich),answers:{},index:0,marking:false,marks:{},aiFeedback:{},markers:{},minutes,end:minutes?Date.now()+minutes*60000:0,id:uid(),saved:false};renderExamSession();if(minutes){timer=setInterval(()=>{const left=Math.max(0,exam.end-Date.now());if($('#examClock'))$('#examClock').textContent=`${Math.floor(left/60000)}:${String(Math.floor(left/1000)%60).padStart(2,'0')}`;if(left===0){captureAnswer();finishExam();toast('Time is up. Review and mark your paper.');}},1000);}}
  function stopTimer(){if(timer)clearInterval(timer);timer=null;}
  function captureAnswer(){if(exam&&$('#examAnswer'))exam.answers[exam.questions[exam.index].id]=$('#examAnswer').value;}
  function renderExamSession(){const q=exam.questions[exam.index];$('#view-exam').innerHTML=heading(exam.marking?'Review & marking':'Practice paper',exam.marking?'Make every mark count.':'One question at a time.',`${exam.questions.length} questions · ${exam.questions.reduce((s,q)=>s+q.marks,0)} marks`,'<button class="small-button" id="exitExam">Exit test</button>')+`<div class="exam-session panel"><div class="exam-session-top"><span class="badge">${esc(q.subject)} · ${esc(q.topic)}</span><span id="examClock">${exam.minutes&&!exam.marking?`${exam.minutes}:00`:'Untimed'}</span></div><div class="test-progress"><i style="width:${(exam.index+1)/exam.questions.length*100}%"></i></div><div class="question-counter">Question ${exam.index+1} of ${exam.questions.length} <span>${q.marks} marks</span></div><h2>${esc(q.prompt)}</h2>${exam.marking?`<div class="your-answer"><span class="eyebrow">Your answer</span><p>${esc(exam.answers[q.id]||'No answer given.')}</p></div><div class="model-answer"><span class="eyebrow">Model answer</span><p>${esc(q.answer)}</p><p class="muted">${q.type==='self'?'Accept accurate, well-explained alternatives.':'Check reasoning and units as well as the final answer.'}</p><ul class="mark-scheme-list">${(q.mark_scheme||[]).map(p=>`<li>${esc(p.text)} <b>${p.marks} mark</b></li>`).join('')}</ul></div><div id="rianMarkPanel"></div><label class="mark-control">Marks awarded (self assessment)<select id="awardedMarks">${Array.from({length:q.marks+1},(_,i)=>`<option value="${i}" ${Number(exam.marks[q.id]??0)===i?'selected':''}>${i} / ${q.marks}</option>`).join('')}</select></label>`:`<label>Your answer<textarea id="examAnswer" rows="7" maxlength="8000" placeholder="Show your reasoning and include units…">${esc(exam.answers[q.id])}</textarea></label>`}<div class="exam-navigation"><button class="small-button" id="prevQuestion" ${exam.index===0?'disabled':''}>← Previous</button><span>${exam.marking?'Compare honestly with the model answer.':'Your answers stay on screen until you finish.'}</span><button class="primary-button" id="nextQuestion">${exam.index===exam.questions.length-1?(exam.marking?'Save results':'Finish & mark'):'Next →'}</button></div></div>`;
    $('#exitExam').onclick=()=>{if(!confirm('Leave this test? Unsubmitted answers will be lost.'))return;stopTimer();exam=null;renderExam();};
    const capture=()=>{captureAnswer();if($('#awardedMarks'))exam.marks[q.id]=Number($('#awardedMarks').value);};$('#prevQuestion').onclick=()=>{capture();exam.index--;renderExamSession();};$('#nextQuestion').onclick=()=>{capture();if(exam.index<exam.questions.length-1){exam.index++;renderExamSession();}else if(exam.marking)saveResults();else finishExam();};if(exam.marking)attachMarking(q);
  }

  function attachMarking(q){
    const session=exam,panel=$('#rianMarkPanel');if(!panel)return;
    const render=()=>{const result=session.aiFeedback[q.id];panel.innerHTML=`<div class="rian-marking"><div><span class="rian-symbol">✦</span><div><strong>Rian AI marking</strong><small>Evidence for every mark. A clearer next step.</small></div></div>${result?`<div class="ai-score">${result.score}<small> / ${result.total}</small></div><ul class="criterion-list">${result.points.map(p=>`<li class="${p.awarded?'awarded':'missed'}"><span>${p.awarded?'✓':'○'}</span><div><strong>${esc(p.criterion)}</strong><p>${esc(p.reason)}</p></div></li>`).join('')}</ul><p class="ai-improvement"><strong>Your next step:</strong> ${esc(result.improvement)}</p><p class="muted">AI feedback can be mistaken. Check the model answer and your teacher’s guidance.</p><button class="primary-button" id="acceptAIMark">Use this suggested mark</button>`:`<p>Compare your answer against the stored marking criteria and get specific improvement advice.</p><button class="primary-button" id="requestAIMark">Mark my answer</button><p class="muted">${aiEnabled?'Your answer is sent to the configured Rian AI provider for feedback.':'Requires the Rian AI key on your server. Self assessment works without it.'}</p><p id="markingError" role="alert"></p>`}</div>`;
      if(result)$('#acceptAIMark').onclick=()=>{session.marks[q.id]=result.score;session.markers[q.id]='Rian AI suggestion accepted';$('#awardedMarks').value=String(result.score);toast('Suggested mark applied. You can still adjust it.');};
      else $('#requestAIMark').onclick=async()=>{const answer=session.answers[q.id]||'';if(!answer.trim()){$('#markingError').textContent='Write an answer first, then request marking.';return;}const btn=$('#requestAIMark');btn.disabled=true;btn.textContent='Rian is checking each criterion…';try{const response=await api('/api/study/mark',{method:'POST',body:JSON.stringify({question_id:q.id,answer})});if(exam!==session)return;session.aiFeedback[q.id]=response.marking;if(session.questions[session.index].id===q.id)render();}catch(error){if(exam===session&&$('#markingError'))$('#markingError').textContent=error.message;}finally{if(exam===session&&$('#requestAIMark')){$('#requestAIMark').disabled=false;$('#requestAIMark').textContent='Try Rian AI marking again';}}};
    };render();
  }
  function finishExam(){stopTimer();exam.marking=true;exam.index=0;renderExamSession();}
  async function saveResults(){if(exam.saved)return;const current=exam;const attempts=current.questions.map((q,i)=>({id:`${current.id}-${i}`,question:q.id,topic:q.topic,subject:q.subject,answer:current.answers[q.id]||'',marker:current.markers[q.id]||'Self assessment',feedback:current.aiFeedback[q.id]?JSON.stringify(current.aiFeedback[q.id]):'',course_id:q.course_id,marks:current.marks[q.id]||0,total:q.marks,date:new Date().toISOString()}));workspace.attempts=workspace.attempts.filter(a=>!attempts.some(b=>b.id===a.id)).concat(attempts).slice(-1000);$('#nextQuestion').disabled=true;if(!await persist()){$('#nextQuestion').disabled=false;return;}current.saved=true;const got=attempts.reduce((s,a)=>s+a.marks,0),total=attempts.reduce((s,a)=>s+a.total,0);$('#view-exam').innerHTML=heading('Practice complete','Progress, one paper at a time.','Your results are saved to your account.')+`<div class="result-panel panel"><div class="result-ring">${Math.round(got/total*100)}<small>%</small></div><h2>${got} out of ${total} marks</h2><p>Assessed against the original model answers and marking criteria.</p><div class="result-breakdown">${attempts.map(a=>`<div><span>${esc(a.topic)}</span><strong>${a.marks}/${a.total}</strong></div>`).join('')}</div><div class="reader-actions"><button class="primary-button" id="reviewGaps">View my progress</button><button class="small-button" id="anotherPaper">Another paper</button></div></div>`;exam=null;$('#reviewGaps').onclick=()=>{renderInsights();Hub.go('insights');};$('#anotherPaper').onclick=renderExam;renderDashboard();}
  function renderPlanner(){const upcoming=workspace.sessions.slice().sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));$('#view-planner').innerHTML=heading('Room to breathe','Your study plan','A realistic timetable built around your subjects and exam dates.','<button class="small-button" id="addExam">＋ Exam date</button><button class="primary-button" id="addSession">＋ Study session</button>')+`<div class="planner-grid"><article class="panel"><span class="eyebrow">Looking ahead</span><h3>Exam countdown</h3><div class="countdown-list">${workspace.exams.map(e=>{const days=Math.ceil((new Date(e.date+'T00:00:00')-new Date(dateISO()+'T00:00:00'))/86400000);return `<div class="countdown"><div><strong>${esc(e.subject)}</strong><small>${esc(e.board)} · ${esc(e.date)}</small></div><b>${days>=0?days:'—'}<small>days</small></b><button class="text-button" data-delete-exam="${esc(e.id)}" aria-label="Remove ${esc(e.subject)} exam">×</button></div>`;}).join('')||'<div class="empty">Add your first exam date.</div>'}</div></article><article class="feature-card blue"><span class="feature-symbol">✦</span><h3>A little, every day.</h3><p>Generate a seven-day plan. Give weaker topics more attention and keep sessions short.</p><label>Daily study time<select id="dailyMinutes"><option value="30">30 minutes</option><option value="60" selected>60 minutes</option><option value="90">90 minutes</option><option value="120">120 minutes</option></select></label><button class="primary-button" id="generatePlan">Plan my week →</button></article></div><article class="panel"><div class="panel-head"><h3>Upcoming study sessions</h3><span class="badge">${upcoming.filter(s=>!s.done).length} to do</span></div><div class="session-list">${upcoming.map(s=>`<div class="session-row ${s.done?'done':''}"><button class="check-session" data-complete="${esc(s.id)}" aria-label="${s.done?'Reopen':'Complete'} ${esc(s.title)}">${s.done?'✓':'○'}</button><div><strong>${esc(s.title)}</strong><small>${esc(s.subject)} · ${esc(s.date)}${s.time?' at '+esc(s.time):''}</small></div><span>${s.minutes} min</span><button class="text-button" data-delete-session="${esc(s.id)}" aria-label="Delete session">×</button></div>`).join('')||'<div class="empty">Make space for your next small win. Add a session or plan your week.</div>'}</div></article>`;
    $('#addExam').onclick=()=>planForm('exam');$('#addSession').onclick=()=>planForm('session');$('#generatePlan').onclick=generatePlan;document.querySelectorAll('[data-complete]').forEach(b=>b.onclick=async()=>{const s=workspace.sessions.find(s=>s.id===b.dataset.complete);s.done=!s.done;await persist();renderPlanner();renderInsights();renderDashboard();});document.querySelectorAll('[data-delete-session]').forEach(b=>b.onclick=async()=>{workspace.sessions=workspace.sessions.filter(s=>s.id!==b.dataset.deleteSession);await persist();renderPlanner();});document.querySelectorAll('[data-delete-exam]').forEach(b=>b.onclick=async()=>{workspace.exams=workspace.exams.filter(s=>s.id!==b.dataset.deleteExam);await persist();renderPlanner();});
  }
  function planForm(kind){modal(`<h2>${kind==='exam'?'Add an exam date':'Plan a study session'}</h2><form id="planForm" class="modal-form"><label>Subject<input name="subject" required maxlength="80" placeholder="e.g. Chemistry"></label>${kind==='exam'?'<label>Exam board<input name="board" maxlength="80" placeholder="e.g. OCR"></label>':'<label>Session title<input name="title" required maxlength="160" placeholder="e.g. Bonding: notes and questions"></label>'}<label>Date<input name="date" type="date" required value="${dateISO()}"></label>${kind==='session'?'<div class="form-two"><label>Start time<input name="time" type="time" value="16:00"></label><label>Minutes<input name="minutes" type="number" required min="5" max="180" value="25"></label></div>':''}<button class="primary-button">Save</button></form>`);$('#planForm').onsubmit=async e=>{e.preventDefault();const item={id:uid(),...Object.fromEntries(new FormData(e.target))};if(item.minutes)item.minutes=Number(item.minutes);workspace[kind==='exam'?'exams':'sessions'].push(item);if(await persist()){close();renderPlanner();}};}
  async function generatePlan(){const daily=Number($('#dailyMinutes').value);const profileSubjects=(Hub.getData().subjects||[]).map(s=>typeof s==='string'?s:s.name);const examSubjects=workspace.exams.filter(e=>e.date>=dateISO()).map(e=>e.subject);const wanted=new Set([...profileSubjects,...examSubjects].map(s=>s.toLowerCase()));let pool=topics.filter(t=>!wanted.size||wanted.has(t.subject.toLowerCase()));if(!pool.length){toast('Add a course that matches the library, or create sessions manually.');return;}const examDate=s=>workspace.exams.filter(e=>e.subject.toLowerCase()===s.toLowerCase()&&e.date>=dateISO()).map(e=>e.date).sort()[0];const urgency=t=>{const when=examDate(t.subject);return (topicAccuracy(t.title)??50)+(when?Math.min(60,Math.ceil((new Date(when+'T00:00:00')-new Date(dateISO()+'T00:00:00'))/86400000))/3:25);};pool.sort((a,b)=>urgency(a)-urgency(b));let added=0;for(let day=0;day<7;day++){const date=new Date();date.setDate(date.getDate()+day);const iso=dateISO(date);const dayPool=pool.filter(t=>!examDate(t.subject)||examDate(t.subject)>=iso);if(!dayPool.length)continue;const existing=workspace.sessions.filter(s=>s.date===iso).reduce((n,s)=>n+Number(s.minutes),0);let remaining=Math.max(0,daily-existing),slot=0;while(remaining>=5){const t=dayPool[(day*2+slot)%dayPool.length];const minutes=Math.min(25,remaining);workspace.sessions.push({id:uid(),subject:t.subject,title:`${t.title}: ${slot%2?'practice questions':'notes & recall'}`,date:iso,time:'',minutes,done:false});remaining-=minutes;slot++;added++;}}if(await persist()){renderPlanner();toast(`${added} sessions added within your daily study budget.`);}}
  function renderInsights(){const sum=workspace.attempts.reduce((s,a)=>s+a.marks,0),total=workspace.attempts.reduce((s,a)=>s+a.total,0);const done=workspace.sessions.filter(s=>s.done);$('#view-insights').innerHTML=heading('See how far you have come','Your progress','Small steps add up. Use your results to choose what comes next.','<button class="small-button" id="exportWorkspace">Export backup</button><button class="small-button" id="restoreWorkspace">Restore backup</button>')+`<div class="insight-stats"><article class="stat-card"><small>Practice accuracy</small><strong>${total?Math.round(sum/total*100)+'%':'—'}</strong><span>${workspace.attempts.length} questions self assessed</span></article><article class="stat-card"><small>Topics read</small><strong>${topics.filter(t=>workspace.completed.includes(t.id)).length}<em> / ${topics.length}</em></strong><span>Keep building understanding</span></article><article class="stat-card"><small>Study time completed</small><strong>${done.reduce((s,a)=>s+a.minutes,0)}<em> min</em></strong><span>${done.length} sessions completed</span></article></div><article class="panel"><div class="panel-head"><h3>Your topic confidence</h3><button class="text-button" id="insightTarget">Build target test →</button></div><div class="confidence-list">${topics.map(t=>{const pct=topicAccuracy(t.title);return `<div class="confidence-row"><div><strong>${esc(t.title)}</strong><small>${esc(t.subject)}</small></div><div class="progress-track"><i style="width:${pct??0}%"></i></div><span>${pct===null?'Unseen':pct+'%'}</span><button class="text-button" data-revisit="${t.id}">Revise →</button></div>`;}).join('')}</div></article><article class="panel"><h3>Recent practice</h3>${workspace.attempts.slice(-8).reverse().map(a=>`<div class="session-row"><div><strong>${esc(a.topic)}</strong><small>${esc(a.date.slice(0,10))}</small></div><span>${a.marks}/${a.total}</span></div>`).join('')||'<p class="muted">Finish your first practice paper to see your results here.</p>'}</article>`;$('#insightTarget').onclick=()=>{Hub.go('exam');renderExam();$('#targetTest').click();};document.querySelectorAll('[data-revisit]').forEach(b=>b.onclick=()=>{selected=b.dataset.revisit;subject='All subjects';search='';renderNotes();Hub.go('notes');});$('#exportWorkspace').onclick=()=>download('revisioncore-backup.json',JSON.stringify({version:1,workspace},null,2),'application/json');$('#restoreWorkspace').onclick=restore;
  }
  function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function exportCards(){const deck=$('#flashcardDeckFilter').value;const cards=(Hub.getData().flashcards||[]).filter(c=>deck==='all'||c.deck===deck);if(!cards.length){toast('Create or import cards first.');return;}modal(`<h2>Take your study set with you</h2><p>${cards.length} cards · ${esc(deck==='all'?'All sets':deck)}</p><p>Download a CSV to share or import elsewhere, or a self-contained flashcard page for offline study.</p><div class="reader-actions"><button class="primary-button" id="cardsCSV">Download CSV</button><button class="small-button" id="cardsOffline">Offline flashcards</button></div>`);$('#cardsCSV').onclick=()=>{const quote=s=>'"'+String(s).replace(/"/g,'""')+'"';download('revisioncore-cards.csv','Question,Answer\r\n'+cards.map(c=>[c.question,c.answer].map(quote).join(',')).join('\r\n'),'text/csv;charset=utf-8');};$('#cardsOffline').onclick=()=>{const safe=JSON.stringify(cards.map(c=>({question:c.question,answer:c.answer}))).replace(/</g,'\\u003c');download('revisioncore-offline.html',`<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RevisionCore · Offline flashcards</title><style>*{box-sizing:border-box}body{font:16px/1.6 system-ui;background:#f2f5fb;color:#14203d;max-width:720px;margin:70px auto;padding:20px}h1{letter-spacing:-1px}button{font:inherit;cursor:pointer;border:1px solid #dce5f2;border-radius:14px;background:white;color:#17315c;padding:12px 22px}#card{width:100%;min-height:300px;margin:25px 0;padding:35px;font-size:25px;border-radius:25px;box-shadow:0 15px 50px #294a7b0e;white-space:pre-wrap}nav{display:flex;justify-content:space-between;align-items:center}small{color:#7b87a0}</style><h1>RevisionCore</h1><p>Offline flashcards · click a card to flip it</p><button id="card" aria-label="Flip flashcard"></button><nav><button id="previous">← Previous</button><small id="position"></small><button id="next">Next →</button></nav><p><small>Space to flip · arrow keys to move · private copy stored in this file</small></p><script>const cards=${safe};let i=0,back=false;function render(){document.querySelector('#card').textContent=back?cards[i].answer:cards[i].question;document.querySelector('#position').textContent=(i+1)+' / '+cards.length}document.querySelector('#card').onclick=()=>{back=!back;render()};document.querySelector('#previous').onclick=()=>{i=(i-1+cards.length)%cards.length;back=false;render()};document.querySelector('#next').onclick=()=>{i=(i+1)%cards.length;back=false;render()};document.onkeydown=e=>{if(e.code==='Space'){e.preventDefault();document.querySelector('#card').click()}if(e.key==='ArrowLeft')document.querySelector('#previous').click();if(e.key==='ArrowRight')document.querySelector('#next').click()};render();<\/script></html>`,'text/html');};}
  function restore(){modal('<h2>Restore your study workspace</h2><p>This replaces your notes, sessions, exam dates and practice history with the backup. Your existing flashcards and account stay separate.</p><input id="backupFile" type="file" accept=".json"><p id="backupError" role="alert"></p>');$('#backupFile').onchange=async e=>{try{const file=e.target.files[0];if(!file||file.size>900000)throw new Error('Choose a RevisionCore backup under 900 KB.');const j=JSON.parse(await file.text());if(j.version!==1||!j.workspace||!['notes','attempts','sessions','exams','bookmarks','completed'].every(k=>Array.isArray(j.workspace[k])))throw new Error('Invalid RevisionCore backup.');if(!confirm('Replace your workspace with this backup?'))return;const result=await api('/api/study/workspace',{method:'PUT',body:JSON.stringify(j.workspace)});workspace={...defaults(),...result.workspace};applyCourses();if(workspace.courses_configured){await api('/api/study/courses',{method:'PUT',body:JSON.stringify({courses:workspace.selected_courses})});await Hub.load();}close();renderAll();toast('Backup restored.');}catch(error){$('#backupError').textContent=error.message;}};}
  function printContent(title,html){let frame=$('#printFrame');if(frame)frame.remove();frame=document.createElement('iframe');frame.id='printFrame';frame.title='Printable revision notes';frame.style.cssText='position:fixed;width:1px;height:1px;left:-10000px;border:0';document.body.append(frame);const doc=frame.contentDocument;doc.open();doc.write(`<!doctype html><html><head><title>${esc(title)}</title><style>body{font:16px/1.7 system-ui;max-width:760px;margin:40px auto;color:#182039}button,.reader-actions{display:none}h2{font-size:32px}h3{margin-top:30px}.exam-tip{padding:18px;border:1px solid #ddd}.muted{color:#777}section{break-inside:avoid}</style></head><body>${html}<footer><hr>RevisionCore · Personal revision copy</footer></body></html>`);doc.close();setTimeout(()=>{frame.contentWindow.focus();frame.contentWindow.print();},250);}
  function renderDashboard(){if(!loaded)return;const data=Hub.getData(),courses=(data.subjects||[]).map(s=>typeof s==='string'?{name:s}:s);let dashboard=$('#studioDashboard');if(!dashboard){dashboard=document.createElement('div');dashboard.id='studioDashboard';$('.welcome').after(dashboard);}
    const shown=courses;const icons=[icon('math'),icon('notes'),icon('science'),icon('science')];const colours=['blue','gold','rose','mint'];const weekday=new Date().toLocaleDateString('en-GB',{weekday:'long'}).toLowerCase();const lessons=(data.timetable||[]).filter(t=>t.day===weekday).sort((a,b)=>a.start.localeCompare(b.start));const total=workspace.attempts.reduce((s,a)=>s+a.total,0),marks=workspace.attempts.reduce((s,a)=>s+a.marks,0);
    dashboard.innerHTML=`<div class="dashboard-courses">${shown.length?'':'<button class="dashboard-course blue" id="dashboardChooseCourses"><span class="course-glyph">＋</span><strong>Choose your courses</strong><small>Bring your exam-board library into focus.</small></button>'}${shown.map((c,i)=>`<button class="dashboard-course ${colours[i%colours.length]}" data-course-open="${esc(c.name)}"><span class="course-glyph">${icons[i%icons.length]}</span><strong>${esc(c.name)}</strong><small>${esc(c.course||'GCSE revision')}</small><span class="course-footer"><i>${c.name.charAt(0)}</i>${esc(c.exam_board||(c.starter?'Explore the library':'Your course'))}</span></button>`).join('')}</div><article class="schedule-panel panel"><div class="panel-head"><div><h3>Class schedule</h3><p>Space for a focused day</p></div><button class="text-button" id="scheduleOpen">View all →</button></div><div class="schedule-plot"><div class="schedule-now"></div>${lessons.length?lessons.slice(0,4).map((t,i)=>{const h=Number(t.start.slice(0,2))+Number(t.start.slice(3,5))/60;const pos=Math.min(77,Math.max(0,(h-8)/9*100));return `<button class="schedule-pill ${i%2?'gold':'blue'}" style="left:${pos}%;top:${30+i*55}px" data-schedule><span>${i%2?'▧':'⚗'}</span><div><strong>${esc(t.subject)}</strong><small>${esc(t.start)}–${esc(t.end)} · ${esc(t.room||'Lesson')}</small></div></button>`;}).join(''):'<div class="schedule-empty"><span>◷</span><strong>Your day, beautifully organised.</strong><p>Add your lessons to see today’s schedule.</p><button class="small-button" id="scheduleAdd">＋ Add a class</button></div>'}</div><div class="schedule-axis">${['8am','9am','10am','11am','12pm','1pm','2pm','3pm','4pm','5pm'].map(t=>`<span>${t}</span>`).join('')}</div></article><aside class="dashboard-score"><div class="accuracy-chip"><strong>${total?Math.round(marks/total*100)+'%':'—'}</strong><small>Accuracy</small></div><button class="gold-tower" id="scoreOpen"><span>★</span><div>${total?'Your practice':'Start your'}<br>${total?'progress':'first practice'}</div><small>${total?workspace.attempts.length+' answers recorded':'Build confidence daily'}</small></button></aside>`;
    dashboard.querySelectorAll('[data-course-open]').forEach(b=>b.onclick=()=>{subject=subjects().includes(b.dataset.courseOpen)?b.dataset.courseOpen:'All subjects';selected=null;search='';renderNotes();Hub.go('notes');});$('#dashboardChooseCourses')?.addEventListener('click',coursePicker);$('#scheduleOpen').onclick=()=>Hub.go('timetable');$('#scheduleAdd')?.addEventListener('click',()=>{$('#addLessonBtn').click();});dashboard.querySelectorAll('[data-schedule]').forEach(b=>b.onclick=()=>Hub.go('timetable'));$('#scoreOpen').onclick=()=>Hub.go(total?'insights':'exam');
    let assignments=$('#studioAssignments');if(!assignments){assignments=document.createElement('article');assignments.id='studioAssignments';assignments.className='assignment-panel';dashboard.after(assignments);}assignments.innerHTML=`<div class="panel-head"><div><h3>Upcoming assignments</h3><p>A clear view of what comes next</p></div><button class="small-button" id="dashboardAddTask">＋ Add task</button></div><div class="assignment-scroll"><table class="assignment-table"><thead><tr><th>Assignment</th><th>Due date</th><th>Subject</th><th>Priority</th><th>Status</th><th></th></tr></thead><tbody>${(data.tasks||[]).slice().sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999')).slice(0,5).map(t=>`<tr><td><span class="assignment-icon">▧</span><div><strong>${esc(t.title)}</strong><small>${esc(t.subject||'School task')}</small></div></td><td>${esc(t.due||'No date')}</td><td>${esc(t.subject||'—')}</td><td>${esc(t.priority||'Normal')}</td><td><span class="status-tag ${t.done?'mint':t.due&&t.due<dateISO()?'gold':'blue'}">${t.done?'Completed':t.due&&t.due<dateISO()?'Overdue':'To do'}</span></td><td><button class="small-button" data-task-open>View details</button></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">All clear. Add homework or a revision deadline to get started.</div></td></tr>'}</tbody></table></div>`;$('#dashboardAddTask').onclick=()=>$('#addTaskBtn').click();assignments.querySelectorAll('[data-task-open]').forEach(b=>b.onclick=()=>Hub.go('tasks'));
    let profile=$('#topProfile');if(!profile){profile=document.createElement('button');profile.id='topProfile';profile.className='top-profile';$('.top-actions').append(profile);}const p=data.profile||{},name=p.display_name||p.username||'Student';profile.innerHTML=`<span class="profile-avatar">${esc(name.charAt(0).toUpperCase())}</span><span><strong>${esc(name)}</strong><small>${esc(p.year_group||'Your study space')}</small></span><span>⌄</span>`;profile.onclick=()=>Hub.go('settings');
  }
  function renderAll(){renderNotes();renderExam();renderPlanner();renderInsights();renderDashboard();renderSetLibrary();lockCourseEditor();}

  function lockCourseEditor(){
    for(const id of ['addSubjectBtn','addCourse'])if($('#'+id))$('#'+id).onclick=coursePicker;
    document.querySelectorAll('#courseEditor input,#courseEditor select').forEach(el=>el.disabled=true);
    document.querySelectorAll('#courseEditor [data-course-delete],.subject-remove').forEach(el=>el.hidden=true);
  }
  function renderSetLibrary(){
    let library=$('#setLibrary');if(!library){library=document.createElement('div');library.id='setLibrary';$('.set-hero').before(library);}
    const data=Hub.getData(),sets=data.flashcard_sets||[],folders=workspace.folders||[];
    library.innerHTML=`<div class="sets-library-head"><div><span class="eyebrow">Your library</span><h2>A little recall. A lot of progress.</h2></div><button class="small-button" id="manageFolders">Folders</button></div><div class="sets-library-tools"><input id="setSearch" type="search" placeholder="Search your study sets"><select id="setFolderFilter" aria-label="Filter study sets by folder"><option value="all">All folders</option>${folders.map(f=>`<option value="${esc(f.id)}">${esc(f.name)}</option>`).join('')}</select></div><div class="study-set-grid" id="studySetGrid"></div>`;
    const draw=()=>{const query=$('#setSearch').value.toLowerCase(),folder=$('#setFolderFilter').value;const shown=sets.filter(set=>set.name.toLowerCase().includes(query)&&(folder==='all'||workspace.set_folders.some(f=>f.set_id===set.id&&f.folder_id===folder)));$('#studySetGrid').innerHTML=shown.map(set=>{const cards=(data.flashcards||[]).filter(c=>c.deck===set.name);const mastered=cards.filter(c=>Number(data.learn_progress?.[c.id]?.mastery)>=2).length;return `<article class="study-set-card"><button class="set-card-open" data-open-set="${esc(set.name)}"><span class="set-card-icon">▣</span><small>${cards.length} terms · ${esc(set.subject||'Personal study')}</small><h3>${esc(set.name)}</h3><p>${esc(set.description||'Pick a mode and make it stick.')}</p><div class="set-card-progress"><i style="width:${cards.length?mastered/cards.length*100:0}%"></i></div><small>${mastered} mastered</small></button><div class="set-card-bottom"><select data-set-folder="${esc(set.id)}" aria-label="Folder for ${esc(set.name)}"><option value="">No folder</option>${folders.map(f=>`<option value="${esc(f.id)}" ${workspace.set_folders.some(x=>x.set_id===set.id&&x.folder_id===f.id)?'selected':''}>${esc(f.name)}</option>`).join('')}</select><button class="text-button" data-copy-set="${esc(set.id)}">Duplicate</button></div></article>`;}).join('')||'<div class="empty">Create your first set or make one from a revision topic.</div>';document.querySelectorAll('[data-open-set]').forEach(b=>b.onclick=()=>{Hub.selectDeck(b.dataset.openSet);$('.set-hero').scrollIntoView({behavior:'smooth',block:'start'});});document.querySelectorAll('[data-set-folder]').forEach(b=>b.onchange=async()=>{workspace.set_folders=workspace.set_folders.filter(x=>x.set_id!==b.dataset.setFolder);if(b.value)workspace.set_folders.push({set_id:b.dataset.setFolder,folder_id:b.value});await persist();});document.querySelectorAll('[data-copy-set]').forEach(b=>b.onclick=async()=>{const set=sets.find(s=>s.id===b.dataset.copySet);const cards=(data.flashcards||[]).filter(c=>c.deck===set.name);if(!cards.length){toast('Add cards before duplicating this set.');return;}try{const text=cards.map(c=>`${c.question.replace(/\t|\n/g,' ')}\t${c.answer.replace(/\t|\n/g,' ')}`).join('\n');await api('/api/student/flashcards/import',{method:'POST',body:JSON.stringify({text,format:'txt',deck:set.name+' (copy)',subject:set.subject||''})});await Hub.load();toast('Study set duplicated.');}catch(error){toast(error.message);}});};
    $('#setSearch').oninput=draw;$('#setFolderFilter').onchange=draw;draw();$('#manageFolders').onclick=()=>{modal(`<h2>Your folders</h2><div class="folder-list">${folders.map(f=>`<div><span>${esc(f.name)}</span><button class="text-button" data-delete-folder="${esc(f.id)}">Remove</button></div>`).join('')}</div><form id="folderForm" class="modal-form"><label>New folder<input name="name" required maxlength="80" placeholder="e.g. Biology paper 1"></label><button class="primary-button">Create folder</button></form>`);$('#folderForm').onsubmit=async e=>{e.preventDefault();const name=new FormData(e.target).get('name').trim();if(!name)return;workspace.folders.push({id:uid(),name});if(await persist()){close();renderSetLibrary();}};document.querySelectorAll('[data-delete-folder]').forEach(b=>b.onclick=async()=>{workspace.folders=workspace.folders.filter(f=>f.id!==b.dataset.deleteFolder);workspace.set_folders=workspace.set_folders.filter(f=>f.folder_id!==b.dataset.deleteFolder);if(await persist()){close();renderSetLibrary();}});};
  }
  function init(){
    document.querySelectorAll('.nav-item[data-view]').forEach(b=>{b.title=b.textContent.trim();b.setAttribute('aria-label',b.textContent.trim());b.querySelector('span').innerHTML=icon(b.dataset.view);});
    $('#cardScope').onchange=e=>Hub.setScope(e.target.value);const exportButton=document.createElement('button');exportButton.className='text-button';exportButton.textContent='Export / offline';exportButton.id='exportStudySet';exportButton.onclick=exportCards;$('.flashcard-toolbar').append(exportButton);
    const signOut=document.createElement('button');signOut.id='mobileSignOut';signOut.className='small-button';signOut.textContent='Sign out';signOut.onclick=()=>$('#logoutButton').click();$('#view-settings .section-title').append(signOut);
    $('#themeToggle').onclick=()=>{document.body.classList.toggle('dark');try{localStorage.setItem('revisioncore-theme',document.body.classList.contains('dark')?'dark':'light');}catch{}};try{document.body.classList.toggle('dark',localStorage.getItem('revisioncore-theme')==='dark');}catch{}
    document.addEventListener('hub:rendered',()=>{if(loaded){renderDashboard();renderSetLibrary();lockCourseEditor();}});
document.addEventListener('hub:loaded',()=>{if(!loaded)load();else renderDashboard();});
    document.addEventListener('click',e=>{if(e.target.closest('#logoutButton')){loaded=false;workspace={};loadGeneration++;stopTimer();exam=null;}if(e.target.closest('[data-go],.nav-item')){const view=e.target.closest('[data-go],.nav-item').dataset.view||e.target.closest('[data-go],.nav-item').dataset.go;if(view==='home'&&loaded)renderDashboard();}});
    document.addEventListener('keydown',e=>{if(e.key==='Tab'&&!$('#modal').hidden){const controls=[...$('#modal').querySelectorAll('button,input,textarea,select,a[href]')].filter(x=>!x.disabled&&!x.hidden);const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
    if(!document.body.classList.contains('logged-out'))load();
  }
  document.addEventListener('DOMContentLoaded',init);
  return {load,renderDashboard,coursePicker};
})();
